import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const beastKingCard='a2-p09-r1c1';
export const beastKingScenarios=['beast-king-ordinary','beast-king-guard','beast-king-owner-ordinary','beast-king-low','beast-king-dedicated','beast-king-nonbeast','beast-king-near','beast-king-same-faction','beast-king-bow','beast-king-spirit','beast-king-null','beast-king-wolf','beast-king-multi','beast-king-multi-fail','beast-king-chant','beast-king-unchanted','beast-king-level-low','beast-king-invalid-co','beast-king-near-far','beast-king-union','beast-king-fate','beast-king-maai-one','beast-king-maai-two','beast-king-evade-restrict','beast-king-suppressed','beast-king-silenced','beast-king-stopped','beast-king-wrong-owner','beast-king-decline','beast-king-counter','beast-king-placed-griffin'] as const;
export type BeastKingScenario=typeof beastKingScenarios[number];
export function isBeastKingScenario(name:string):name is BeastKingScenario{return (beastKingScenarios as readonly string[]).includes(name);}
export function beastKingMode(name:BeastKingScenario){const suffix=name.replace('beast-king-',''),dedicated=!['ordinary','guard','owner-ordinary','low','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',guard=!['ordinary','low','decline'].includes(suffix),chant=['multi','multi-fail','chant'].includes(suffix),near=['near','wolf','union'].includes(suffix),co=({bow:'a2-p24-r1c2',spirit:'a2-p08-r3c3',null:'a2-p08-r3c2',wolf:'a2-p10-r3c1',multi:'a2-p10-r1c3','multi-fail':'a2-p10-r1c3',chant:'a2-p11-r3c3',unchanted:'a2-p11-r3c3','level-low':'a2-p08-r3c3','invalid-co':'a2-p24-r1c2','near-far':'a2-p08-r3c1',union:'a2-p09-r1c3',fate:'a2-p08-r3c3','maai-one':'a2-p08-r1c1','maai-two':'a2-p08-r1c1','evade-restrict':'a2-p08-r2c2',counter:'a2-p08-r2c3','placed-griffin':'a2-p20-r3c1'} as Record<string,string>)[suffix];return {suffix,dedicated,owner,guard,chant,near,co,coDedicated:suffix==='placed-griffin'};}
export function makeBeastKingPhysical(name:BeastKingScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number}={}){
 const m=beastKingMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix);let s=createGame(players,entropy(),{startingSeat:prior?3:m.suffix==='counter'?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'獣使いのウパニシャット':'侍大将のシン',m.owner?'侍大将のシン':'黒騎士ガーウィン','黒妖精のアーネス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=6-gameStats(s,p.id).spirit;}
 const warrior=options.warrior??(['low','level-low'].includes(m.suffix)?5:m.chant||m.suffix==='unchanted'?7:m.co?6:m.dedicated?0:6);s.players[a]!.permanent!.warrior_level!+=warrior-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,beastKingCard),takeCard(s,d,'a2-p02-r2c3')];if(m.co)keep.push(takeCard(s,a,m.co));if(m.guard)keep.push(takeCard(s,b,m.suffix==='nonbeast'?'a2-p22-r3c3':'a2-p23-r1c1'),takeCard(s,c,'a2-p18-r3c3'));
 if(m.near||m.suffix==='near-far')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(m.suffix.startsWith('maai'))keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p07-r1c1'));if(m.suffix==='evade-restrict')keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.suffix==='counter')keep.push(takeCard(s,b,'a2-p24-r2c2'));
 if(m.suffix==='invalid-co')keep.push(takeCard(s,a,'a2-p12-r2c2'),takeCard(s,a,'a2-p05-r3c1'),takeCard(s,a,'a2-p08-r3c3'),takeCard(s,b,'a2-p24-r2c2'));
 if(m.suffix==='union')keep.push(takeCard(s,b,'a2-p22-r3c3'),takeCard(s,d,'a2-p01-r2c1'));
 if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(m.suffix==='union'){s.players[d]!.hand=s.players[d]!.hand.filter(id=>id!=='a2-p01-r2c1');s.deck.unshift('a2-p01-r2c1');}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`BEAST_KING_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('BEAST_KING_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('BEAST_KING_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('BEAST_KING_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.suffix==='placed-griffin'&&id===a)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p20-r3c1'});if(m.guard&&(id===b||id===c)){act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:id===b?m.suffix==='nonbeast'?'a2-p22-r3c3':'a2-p23-r1c1':'a2-p18-r3c3'});if(m.suffix==='union'&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p22-r3c3'});}act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=m.suffix==='counter'?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});
 if(m.chant){act(a,{type:'CHANT',cardInstanceId:m.co!});act(a,{type:'END_TURN',discardIds:[]});settle();for(const id of [b,c,d]){act(id,{type:'START_TURN'});settle();act(id,{type:'CHOOSE_DRAW',draw:false});act(id,{type:'PASS_ACTION'});act(id,{type:'END_TURN',discardIds:[]});settle();}act(a,{type:'START_TURN'});settle();act(a,{type:'CHOOSE_DRAW',draw:false});}
 if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}if(m.near){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}
 if(m.suffix==='counter'){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r2c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('BEAST_KING_FIXTURE_COUNTER_LIMIT');}return s;
}
